// The prior FULL ISO week (Monday..Sunday), computed defensively via document-builder.ts's own
// mondayOnOrBefore()/addDaysIso() arithmetic (not a bare '-7 days from today') so a manual
// off-schedule test-trigger still lands on the correct Monday rather than an arbitrary date.
function toUtcDate(iso) { return new Date(`${iso}T00:00:00.000Z`); }
function fromUtcDate(d) { return d.toISOString().slice(0, 10); }
function mondayOnOrBefore(iso) {
  const d = toUtcDate(iso);
  const dow = (d.getUTCDay() + 6) % 7; // 0 = Monday
  d.setUTCDate(d.getUTCDate() - dow);
  return fromUtcDate(d);
}
function addDays(iso, n) {
  const d = toUtcDate(iso);
  d.setUTCDate(d.getUTCDate() + n);
  return fromUtcDate(d);
}
const today = new Date().toISOString().slice(0, 10);
const priorMonday = addDays(mondayOnOrBefore(today), -7);
return [{ json: { start: priorMonday } }];

// GET /reports/periods?kind=week&from=X&to=X ALWAYS vivifies+returns exactly one row for a
// single-Monday range (report-periods.ts's enumerateCalendarStarts, week case) -- trusted here the
// same way nightly-facts trusts its own computed window, not defensively re-validated.
const body = $input.first().json.body ?? $input.first().json;
const period = body.periods[0];
return [{ json: { periodId: period.id, periodStart: period.periodStart, periodEnd: period.periodEnd } }];

// The recheck IS the idempotency check (this ticket's explicit instruction: '409 = success-
// already-done, not a failure to alert on'). Rather than parse the failed seal call's error body
// for a status code, ask the resource itself: if it is now 'sealed' -- by THIS flow's earlier run,
// a human, or a genuine concurrent race, it doesn't matter which -- proceed exactly as if this run
// had sealed it. Only a period still 'open'/'amended' after the recheck is a genuine failure.
const body = $input.first().json.body ?? $input.first().json;
const ex = $('Extract period').first().json;
if (body.status === 'sealed') {
  return [{ json: { ok: true, periodId: ex.periodId, periodStart: ex.periodStart, periodEnd: ex.periodEnd } }];
}
return [{ json: { ok: false, periodId: ex.periodId, status: body.status, reason: 'seal call failed and period is still ' + body.status } }];

// Every department scope with in-range data (§10: "all grains/scopes") + the single company
// scope (report-seal.ts always includes it, never emitted as an `overview` row itself).
const body = $input.first().json.body ?? $input.first().json;
const sealCtx = $('Sealed ok?').first().json;
const deptScopes = (body.scopes || []).map((s) => ({ grain: 'department', scopeRef: s.scopeRef, scopeName: s.scopeName }));
const all = [...deptScopes, { grain: 'company', scopeRef: $env.AGENCY_TENANT_ID, scopeName: 'Company' }];
return all.map((s) => ({ json: { ...s, periodId: sealCtx.periodId, periodStart: sealCtx.periodStart, periodEnd: sealCtx.periodEnd } }));

// Deep-link into the sealed document via the SAME href shape report-seal.ts's own amend-notify
// uses (`/reports?periodId=...`) -- a LINK, never the numbers themselves (§11). The rendered PDF
// itself (already persisted by the export call above) is reachable from that same viewer page.
const j = $json;
return [{ json: { ok: true, grain: j.grain, scopeRef: j.scopeRef, scopeName: j.scopeName, href: `/reports?periodId=${j.periodId}&grain=${j.grain}&scopeRef=${j.scopeRef}` } }];

// Per-scope isolation: a render failure for ONE department must not stop the others (n8n
// processes each input item to 'POST export' independently) -- this scope drops into the
// dead-letter summary below while every other scope's export/notify proceeds normally.
const j = $json;
const err = j.error ?? j;
return [{ json: { ok: false, grain: j.grain, scopeRef: j.scopeRef, scopeName: j.scopeName, error: String(err?.message ?? err) } }];

// Fan-in from BOTH the success and failure branches above (two incoming connections into this
// same Code node) -- $input.all() sees every item regardless of which branch it came from.
const items = $input.all().map((i) => i.json);
const links = items.filter((i) => i.ok);
const failures = items.filter((i) => !i.ok);
const sealCtx = $('Sealed ok?').first().json;
return [{ json: { periodId: sealCtx.periodId, periodStart: sealCtx.periodStart, periodEnd: sealCtx.periodEnd, links, failures } }];

// One in-app notification per configured reports stakeholder (README's disclosed scoping
// decision: a static list, not a live Cerbos role query), carrying every successfully-rendered
// scope's link (never the KPI numbers themselves, §11) plus a count of any scope that failed to
// render so a human knows to check, without that failure blocking the scopes that DID succeed.
const summary = $json;
const ids = String($env.REPORTS_NOTIFY_USER_IDS || '').split(',').map((s) => s.trim()).filter(Boolean);
return ids.map((recipientId) => ({
  json: {
    tenantId: $env.AGENCY_TENANT_ID,
    recipientId,
    type: 'reports_weekly_sealed',
    periodId: summary.periodId,
    periodStart: summary.periodStart,
    periodEnd: summary.periodEnd,
    links: summary.links,
    failureCount: summary.failures.length,
  },
}));

// Dead-letter payload for every failure branch that reaches here: the seal call genuinely failed
// (not merely raced to a 409), or a network node exhausted its 3 retries. Never fires for the
// idempotent-already-sealed case -- that is the whole point of the recheck above.
const j = $input.first().json;
const err = j.error ?? j;
return [{ json: { start: $('Compute prior ISO week').first().json.start, reason: j.reason ?? String(err?.message ?? err) } }];
